double uniform_random(double min, double max, unsigned int& seed, unsigned int a, unsigned int c, unsigned int m) {
    if (m == 0) return min;
    seed = (a * seed + c) % m;
    double range = max - min;
    double random_fraction = static_cast<double>(seed) / static_cast<double>(m);
    return min + range * random_fraction;
}

